refresh().then(()=>handleRecoveryLink()).catch(e=>{$('#main').innerHTML=`<div class="empty-state"><span>◌</span>暂时无法连接世界。<br>${esc(e.message)}<br><button class="button secondary" id="retry">重新连接</button></div>`;$('#retry').onclick=()=>location.reload();});
let updateTimer=null;
function scheduleUpdate(){if(updateTimer)return;updateTimer=setTimeout(()=>{updateTimer=null;if(document.hidden||busy){scheduleUpdate();return;}refresh(true,true).catch(()=>{$('.connection').textContent='连接中断，正在重试…';});},160);}
if(!quickTunnel){
 const stream=new EventSource('/api/stream');
 stream.onmessage=()=>scheduleUpdate();
 stream.onerror=()=>{$('.connection').textContent='实时连接重连中…';};
}
setInterval(()=>{if(!document.hidden&&!busy)refresh(true,true).catch(()=>{});},15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)scheduleUpdate();});
